CameraUtil = {}


---起始点到目标点的yaw和pitch值
---@param fromPos Vector3
---@param targetPos Vector3
function CameraUtil.getPitchAndYaw(fromPos, targetPos)
    local vector = math.atan2(targetPos.x - fromPos.x, targetPos.z - fromPos.z)
    local yaw = vector / math.pi * -180

    local dir = VectorUtil.sub3(targetPos, fromPos)
    local pitch = MathUtil.GetVector3Angle(VectorUtil.newVector3(dir.x, 1, dir.z), dir)

    return yaw, pitch
end

---第三人称视角距离
---@param distance number
function CameraUtil.setThirdPersonDistance(distance)
    ClientHelper.putFloatPrefs("ThirdPersonDistance", distance)
end

---相机和人物旋转分离
---@param isSeparate boolean
function CameraUtil.setIsSeparateCamera(isSeparate)
    ClientHelper.putBoolPrefs("IsSeparateCamera", isSeparate)
end

---禁止移动和跳跃
function CameraUtil:disableMove()
    ClientHelper.putBoolPrefs("DisableMovement", true)
    GUIManager:hideMainControllerUI()
end

---取消禁止移动和跳跃
function CameraUtil:enableMove()
    ClientHelper.putBoolPrefs("DisableMovement", false)
    GUIManager:showMainControllerUI()
end




